create table if not exists sync_run (id bigint not null auto_increment comment 'sync run primary key', run_no varchar(32) not null comment 'run number', sync_type varchar(32) not null comment 'sync type', status varchar(32) not null comment 'status', created_at datetime(3) not null default current_timestamp(3) comment 'created time', primary key(id), unique key uk_sync_run_no(run_no)) engine=InnoDB default charset=utf8mb4 comment='wecom sync run';
create table if not exists sync_event (id bigint not null auto_increment comment 'event primary key', event_no varchar(32) not null comment 'event number', provider varchar(32) not null comment 'provider', event_type varchar(128) not null comment 'event type', payload_hash varchar(128) not null comment 'payload hash', status varchar(32) not null comment 'status', sync_run_id bigint comment 'sync run id', received_at datetime(3) not null default current_timestamp(3) comment 'received time', primary key(id), unique key uk_sync_event_no(event_no)) engine=InnoDB default charset=utf8mb4 comment='wecom sync event';

